'use strict';

// Shared page composition. Collection and media workers remain in workbench.js.
const pageMeta={home:['工作台','从真实作品开始，继续你的下一步研究。'],mine:['我的抖音账号','账号与作品保存在当前工作台。'],accounts:['对标账号','找到值得研究的账号，积累有来源的内容样本。'],account:['作品研究','查看作品、文案和评论，选择这次要研究的样本。'],materials:['素材与文案','已保存的视频与全文，在这里直接查看和使用。'],reports:['研究报告','保留每次研究的结论与来源。'],report:['阅读研究报告','结论与原始资料相互对应。'],tasks:['任务中心','处理进度与结果集中查看。'],settings:['设置与帮助','管理工作台、组件与本机数据。'],cloud:['体验灵思云端','从单次研究，走向持续内容运营。']};
function pageHead(title,description,buttons=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${buttons}</div></div>`;}
function emptyState(title,description,button=''){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(description)}</p>${button}</div>`;}
function panelTitle(title,link,label='查看全部'){return `<div class="section-title"><h2>${esc(title)}</h2>${link?`<a class="text-button" href="${esc(link)}">${esc(label)} →</a>`:''}</div>`;}
function productHealth(){const d=state.data||{},c=d.connection||{},cap=d.capabilities||{};return `<div class="health-grid"><div><span class="status-dot"></span><strong>本地服务</strong><span>已连接 · v${esc(d.version||'')}</span></div><div><span class="status-dot ${c.status==='connected'?'':'pending'}"></span><strong>抖音连接</strong><span>${c.status==='connected'?'已识别 '+esc(c.identity?.name||'账号'):c.browser_open?'等待登录确认':'尚未连接'}</span></div><div><span class="status-dot ${cap.model_ready?'':'pending'}"></span><strong>转写模型</strong><span>${cap.model_ready?'已准备':cap.transcription_installed?'待准备模型':'待安装组件'}</span></div></div>`;}
function syncPageHeader(){
 if(typeof syncCloudEngine==='function')syncCloudEngine();
 const page=location.hash.slice(1).split('/')[0]||'home',head=$('#main > .page-head');
 $('#page-title').textContent=head?.querySelector('h1')?.textContent||pageMeta[page]?.[0]||'工作台';
 $('#page-description').textContent=head?.querySelector('p')?.textContent||pageMeta[page]?.[1]||'';
 $('#page-actions').replaceChildren();if(head){const controls=head.querySelector(':scope > .actions');if(controls)$('#page-actions').append(...controls.childNodes);head.remove();}
 $('#account-context').textContent=state.data?.profile?.name||'选择工作台';
 $('#breadcrumb').textContent=pageMeta[page]?.[0]||'工作台';
 $('#materials-count').textContent=(state.data?.posts||[]).filter(p=>p.transcript||p.media_path).length;
 $('#mobile-page-label').textContent=pageMeta[page]?.[0]||'工作台';
 document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');
 syncNavigationAccess();
 if(page==='materials')renderMaterials();if(page==='accounts')renderAccountLibrary();if(page==='account'&&state.account?.sec_uid===state.data.binding?.sec_uid){const back=$('.back-link');if(back){back.href='#mine';back.textContent='← 我的抖音账号';}}
 if(page==='report')setupReportDirectory();
 updateActivity();
}
homePage=function(){
 const d=state.data,own=d.accounts.find(a=>a.sec_uid===d.binding?.sec_uid),competitors=d.accounts.filter(a=>a.sec_uid!==d.binding?.sec_uid),ready=d.posts.filter(p=>p.transcript),active=d.jobs.filter(activeJob),latest=d.reports[0];
 const next=latest?`<small>继续最近的研究</small><h2>${esc(latest.title)}</h2><p>${esc(reportPhaseLabels[latest.phase||'waiting']||'等待 AI 研究')}</p><a class="button" href="#report/${latest.id}">继续研究 →</a>`:ready.length?`<small>下一步</small><h2>文案已就绪，开始研究作品</h2><p>从 ${ready.length} 条有文案的作品中，选择这次要学习的样本。</p><a class="button" href="#materials">查看素材与文案 →</a>`:`<small>下一步</small><h2>${competitors.length?'打开作品，开始第一次研究':'添加一个你想研究的账号'}</h2><p>粘贴抖音主页或作品链接，读取真实作品与互动数据。</p><button class="button" data-action="collect-link">粘贴对标链接</button>`;
 return `${pageHead('工作台','让每一次观察，都能回到真实作品。','<button class="button" data-action="collect-link">＋ 采集对标账号</button>')}${demoNotice()}${!d.accounts.length?`<div class="start-options"><section class="panel"><small>从自己的账号开始</small><h2>看我的抖音数据</h2><p>扫码登录，自动同步公开作品和互动数据。</p><button class="button" data-action="start-login">连接我的抖音</button></section><section class="panel"><small>从一个对标开始</small><h2>研究值得学习的内容</h2><p>已有抖音链接，直接粘贴即可采集。</p><button class="button secondary" data-action="collect-link">粘贴对标链接</button></section></div><button class="text-button" data-action="demo">先看演示效果 →</button>`:`<div class="stats four">${[[competitors.length,'对标账号'],[d.posts.length,'已保存作品'],[ready.length,'文案已就绪'],[d.reports.filter(r=>r.status==='completed').length,'已完成研究']].map(([n,label])=>`<div class="stat"><small>${label}</small><strong>${n}</strong></div>`).join('')}</div><div class="dashboard-grid"><section class="panel next-action">${next}</section><section class="panel"><small>当前账号</small><div class="account-title spaced">${own?avatar(own):'<img class="avatar" src="/icon.png" alt="">'}<div><h3>${esc(own?.name||'还没有关联自己的账号')}</h3><p>${own?'已保存 '+countPosts(own.sec_uid).length+' 条作品':'登录后自动识别与同步作品'}</p></div></div><a class="button secondary" href="#mine">${own?'管理我的账号':'连接抖音账号'}</a></section></div>${panelTitle('最近的对标账号','#accounts')}<div class="cards">${competitors.slice(0,3).map(accountCard).join('')||emptyState('还没有对标账号','可以先查看自己的作品，再添加对标。','<button class="text-button" data-action="collect-link">采集对标账号 →</button>')}</div>${panelTitle(active.length?'正在处理':'最近任务','#tasks','任务中心')}<div id="home-jobs">${d.jobs.length?jobRows(active.length?active.slice(0,2):d.jobs.slice(0,2)):emptyState('暂无任务','采集与转写的进度会显示在这里。')}</div>`}`;
};
accountCard=function(a){const posts=countPosts(a.sec_uid);return `<article class="account-card"><div class="account-title">${avatar(a)}<div><h3>${esc(a.name)}</h3><small>${a.demo?'虚构演示':a.collected_at?'采集于 '+date(a.collected_at):'本地资料'}</small></div></div><p>${esc(a.bio||'暂无账号简介')}</p><div class="account-meta"><span><strong>${fmt(a.followers)}</strong>粉丝</span><span><strong>${posts.length}</strong>已保存作品</span><span><strong>${posts.filter(p=>p.transcript).length}</strong>有文案</span></div><div class="card-footer"><span class="pill">${a.demo?'演示账号':'对标账号'}</span><a class="button secondary small" href="#account/${encodeURIComponent(a.sec_uid)}">查看作品 →</a></div></article>`;};
accountsPage=function(){return `${pageHead('对标账号','集中管理你的对标，继续观察值得学习的作品。','<button class="button" data-action="collect-link">＋ 采集对标账号</button>')}${demoNotice()}<div class="toolbar"><input id="account-search" type="search" placeholder="搜索账号名称或简介" aria-label="搜索对标账号" value="${esc(state.accountQuery||'')}"><div class="actions"><select id="account-sort" aria-label="对标账号排序"><option value="recent">最近采集</option><option value="followers">粉丝最多</option><option value="works">保存作品最多</option></select><button class="text-button" data-action="new-account">手动建档</button><button class="button secondary small" data-action="import">导入已有资料</button></div></div><div id="account-library"></div>`;};
function renderAccountLibrary(){if(!$('#account-library'))return;const list=state.data.accounts.filter(a=>a.sec_uid!==state.data.binding?.sec_uid&&(a.name+' '+a.bio).toLowerCase().includes((state.accountQuery||'').toLowerCase())).sort((a,b)=>state.accountSort==='followers'?(b.followers||0)-(a.followers||0):state.accountSort==='works'?countPosts(b.sec_uid).length-countPosts(a.sec_uid).length:String(b.collected_at||b.updated_at||'').localeCompare(String(a.collected_at||a.updated_at||'')));$('#account-sort').value=state.accountSort||'recent';$('#account-library').innerHTML=list.length?`<div class="cards">${list.map(accountCard).join('')}</div>`:emptyState('没有匹配的对标账号','粘贴抖音主页或作品链接，开始积累真实样本。','<button class="button" data-action="collect-link">粘贴链接开始采集</button>');}
accountPage=function(a){const posts=countPosts(a.sec_uid);return `${pageHead('作品研究','播放、阅读和比较，再选择你的研究样本。','<button class="button" data-action="sync">刷新抖音作品</button>')}${demoNotice()}<a class="back-link" href="#accounts">← 全部对标账号</a><section class="panel detail-heading">${avatar(a)}<div><h2>${esc(a.name)}</h2><p>${esc(a.bio||'暂无简介')}</p><div class="account-meta"><span>粉丝 <strong>${fmt(a.followers)}</strong></span><span>已保存 <strong>${posts.length}</strong></span><span>有文案 <strong>${posts.filter(p=>p.transcript).length}</strong></span>${a.url?`<a class="text-button" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">账号主页 ↗</a>`:''}</div></div></section><div class="toolbar"><input class="search" id="work-search" type="search" aria-label="搜索作品标题或文案" placeholder="搜索作品标题或文案" value="${esc(state.query)}"><div class="actions"><select id="work-sort" aria-label="作品排序"><option value="published_at">最新发布</option><option value="likes">点赞最多</option><option value="collects">收藏最多</option><option value="comments">评论最多</option><option value="shares">分享最多</option></select><div class="segmented"><button class="button secondary small" data-action="work-grid">封面视图</button><button class="button secondary small" data-action="work-table">数据表格</button></div><details class="more-actions"><summary>更多</summary><div><button class="text-button" data-action="new-post">添加作品</button><button class="text-button" data-action="import">导入作品</button><a class="text-button" href="${esc(scoped('/api/account/export',{sec_uid:a.sec_uid}))}">导出账号资料</a></div></details></div></div><div id="work-table"></div><div class="selection-bar" hidden><span>已选 <strong id="selected-count">0</strong> 条作品</span><div class="actions"><button class="button secondary small" data-action="download-selected">采集视频</button><button class="button secondary small" data-action="transcribe-selected">转写所选</button><button class="button secondary small" data-action="comments-selected">采集评论</button><button class="button secondary small" data-action="breakdown-selected">单条拆解</button><button class="button small" data-action="create-report" id="create-report-button">开始 AI 研究 →</button></div></div><div class="list-end"><button class="button secondary" data-action="load-more">继续加载作品</button><small>展示的是已采集样本，未知互动数显示“—”。</small></div>`;};
const studioRenderWorks=renderWorks;
renderWorks=function(){studioRenderWorks();const bar=$('.selection-bar');if(bar)bar.hidden=state.selected.size===0;document.querySelectorAll('[data-action="work-grid"],[data-action="work-table"]').forEach(el=>el.setAttribute('aria-pressed',String((state.workView==='table')===(el.dataset.action==='work-table'))));};
function materialsPage(){return `${pageHead('素材与文案','打开已保存的视频，阅读、复制和导出完整文案。','<a class="button" href="#accounts">选择作品 →</a>')}${demoNotice()}<div class="toolbar"><input type="search" id="material-search" placeholder="搜索作品标题或文案" aria-label="搜索素材" value="${esc(state.materialQuery||'')}"><div class="actions"><select id="material-account" aria-label="按账号筛选素材"><option value="">全部账号</option>${state.data.accounts.map(a=>`<option value="${esc(a.sec_uid)}" ${a.sec_uid===state.materialAccount?'selected':''}>${esc(a.name)}</option>`).join('')}</select><select id="material-filter" aria-label="素材状态"><option value="all">全部已保存素材</option><option value="transcript">有文案</option><option value="video">已下载视频</option><option value="failed">处理异常</option></select></div></div><div id="material-list"></div>`;}
function renderMaterials(){if(!$('#material-list'))return;$('#material-filter').value=state.materialFilter||'all';const filter=state.materialFilter||'all',q=(state.materialQuery||'').toLowerCase();const posts=state.data.posts.filter(p=>(!state.materialAccount||p.sec_uid===state.materialAccount)&&(p.title+' '+p.transcript).toLowerCase().includes(q)&&(filter==='transcript'?p.transcript:filter==='video'?p.media_path:filter==='failed'?p.processing_error&&p.media_type!=='gallery':p.transcript||p.media_path||p.processing_error&&p.media_type!=='gallery'));$('#material-list').innerHTML=posts.length?`<p class="result-count">${posts.length} 条素材 · 当前工作台</p><div class="material-list">${posts.map(p=>`<article class="material-row"><button class="material-cover" data-action="preview-video" data-id="${esc(p.aweme_id)}" aria-label="预览 ${esc(p.title)}">${p.image_path?`<img src="${esc(imageSource('post',p.aweme_id))}" alt="" loading="lazy">`:'<span>查看</span>'}</button><div class="material-content"><button class="work-preview-title" data-action="preview-video" data-id="${esc(p.aweme_id)}">${esc(p.title)}</button><small>${esc(state.data.accounts.find(a=>a.sec_uid===p.sec_uid)?.name||'')} · ${date(p.published_at)}</small><p>${esc(p.transcript?.slice(0,120)||p.processing_error||'视频已保存，可以开始转写。')}</p><div class="actions"><span class="pill">${p.transcript?p.transcript.length+' 字文案':p.media_path?'视频已下载':'待处理'}</span><button class="text-button" data-action="preview-transcript" data-id="${esc(p.aweme_id)}">${p.transcript?'阅读全文':'查看作品'}</button>${p.transcript?`<button class="text-button" data-action="copy-material" data-id="${esc(p.aweme_id)}">复制文案</button><button class="text-button" data-action="export-material" data-id="${esc(p.aweme_id)}">导出 TXT</button>`:''}</div></div></article>`).join('')}</div>`:emptyState('这里还没有匹配的素材','到对标作品页选择视频，下载或转写后会自动出现在这里。','<a class="button secondary" href="#accounts">查看对标账号</a>');}
reportsPage=function(){const reports=state.data.reports;return `${pageHead('研究报告','查看已完成的研究，或继续待开始研究的资料。','<a class="button" href="#accounts">开始新的研究 →</a>')}${demoNotice()}${reports.length?`<div class="report-list">${reports.map(r=>`<article class="report-row"><div><span class="pill">${r.report_type==='breakdown'?'单条拆解':'账号研究'}</span><h3>${esc(r.title)}</h3><small>${esc(r.account_name||r.snapshot?.account?.name||'')} · ${r.source_count??r.snapshot?.sources?.length??'—'} 条来源 · 更新于 ${date(r.updated_at||r.created_at)}</small></div><div class="actions"><span class="pill ${r.status==='completed'?'good':'waiting'}">${esc(reportPhaseLabels[r.phase||'waiting']||'待开始研究')}</span><a class="button secondary" href="#report/${r.id}">${r.status==='completed'?'阅读报告':'继续研究'} →</a></div></article>`).join('')}</div>`:emptyState('你的第一份研究，从作品开始','选择有文案的作品，使用 AI 接口 完成有来源的基础研究。','<a class="button" href="#accounts">去选择作品</a>')}`;};
reportPage=function(r){const done=r.status==='completed';return `${pageHead(r.title,`${r.snapshot.sources.length} 条来源作品 · ${date(r.created_at)}`,`<a class="button secondary" href="${esc(scoped('/api/report/export',{id:r.id}))}">导出 Markdown</a>`)}<a class="back-link" href="#reports">← 全部研究报告</a>${demoNotice()}<section class="panel" id="report-progress">${reportProgress(r)}</section>${!done?`<section class="panel ai-report-controls"><h2>通过 AI 接口完成研究</h2>${r.batch_id?`<p class="help-note">这里仅处理当前报告。<a class="text-button" href="#batch/${r.batch_id}">查看整批进度 / 恢复整批 →</a></p>`:''}<p>${esc(r.api_error||'使用设置中配置的模型，分析这份报告的来源并自动保存。')}</p><div class="actions"><button class="button" data-action="report-run-ai" ${r.api_requested||r.status==='analyzing'?'disabled':''}>${r.api_requested||r.status==='analyzing'?r.phase==='waiting'?'已排队，等待处理…':'研究进行中…':state.data.ai?.configured?(r.phase==='failed'?'重试当前报告':'开始当前报告'):'配置 AI 接口'}</button>${r.api_requested||r.status==='analyzing'?'<button class="button secondary" data-action="report-cancel-ai">停止当前报告</button>':''}<a class="text-button" href="#settings">AI 接口设置 →</a></div></section>`:''}<div class="report-layout"><article class="report-paper">${done?markdown(r.markdown):`<details><summary>查看本次来源资料</summary>${r.snapshot.sources.map(p=>`<h3>${esc(p.title)}</h3><p>${esc(p.transcript)}</p>`).join('')}</details>`}</article><aside class="report-aside"><section class="mini-panel"><h3>阅读目录</h3><div id="report-directory"></div><details class="spaced"><summary>来源作品 · ${r.snapshot.sources.length} 条（查看当前资料）</summary>${r.snapshot.sources.map(p=>`<p><button class="text-button" data-action="preview-transcript" data-id="${esc(p.aweme_id)}">${esc(p.title)}</button><small>${esc(p.aweme_id)}</small></p>`).join('')}</details><a class="text-button" href="${esc(scoped('/api/report/packet',{id:r.id}))}">导出来源快照</a><button class="text-button" data-action="edit-report">${done?'编辑 / 导入报告':'导入已完成报告'}</button></section>${done?'<section class="mini-panel cloud-note"><h3>把研究接到持续创作</h3><p>在云端继续了解对标跟踪、选题脚本与发布复盘。</p><a class="button secondary small" href="#cloud">了解云端完整体验 →</a></section>':''}</aside></div>`;};
function setupReportDirectory(){const headings=[...document.querySelectorAll('.report-paper h1,.report-paper h2,.report-paper h3,.report-paper h4,.report-paper h5,.report-paper h6')];if($('#report-directory'))$('#report-directory').innerHTML=headings.map((h,i)=>`<button class="toc-link" data-action="report-section" data-index="${i}">${esc(h.textContent)}</button>`).join('')||'<p class="help-note">开始研究后生成内容目录。</p>';}
tasksPage=function(){const cap=state.data.capabilities||{};return `${pageHead('任务中心','查看当前阶段，完成后直接打开对应结果。','<button class="button secondary" data-action="refresh">刷新状态</button>')}${demoNotice()}<details class="component-details"><summary>本地中文转写 <span class="pill ${cap.model_ready?'good':'waiting'}">${cap.model_ready?'模型已准备':'待准备'}</span></summary><div><p>${cap.transcription_installed?'转写组件已安装，模型在本机运行。':'请先安装转写组件，再准备模型。'}</p><div class="actions"><button class="button secondary small" data-action="prepare-model">${cap.model_ready?'检查模型可用性':'准备转写模型'}</button><button class="text-button" data-action="component-help">安装说明</button></div></div></details><div id="task-list">${taskContent()}</div>`;};
minePage=function(){
 const d=state.data,c=d.connection||{},flow=c.workflow||{},a=d.accounts.find(x=>x.sec_uid===d.binding?.sec_uid),posts=a?countPosts(a.sec_uid):[],busy=['queued','running'].includes(flow.status),stage=flow.status==='completed'?4:a?2:c.status==='connected'?1:0;
 return `${pageHead('我的抖音账号','扫码连接后，自动识别账号并同步作品。',c.status==='connected'?`<button class="button" data-action="read-mine" ${busy?'disabled':''}>${busy?'正在同步作品…':'刷新作品数据'}</button>`:'<button class="button" data-action="connect-douyin">连接抖音并同步作品</button>')}${demoNotice()}<section class="panel own-summary"><div class="account-title">${a?avatar(a):'<img class="avatar" src="/icon.png" alt="">'}<div><h2>${esc(a?.name||'连接我的抖音')}</h2><p>${a?'当前工作台：'+esc(d.profile?.name||''):'在打开的抖音窗口扫码，无需填写账号信息。'}</p></div>${connectionBadge()}</div>${a?`<div class="metric-inline spaced"><span>粉丝 <b>${fmt(a.followers)}</b></span><span>获赞 <b>${fmt(a.total_favorited)}</b></span><span>已保存作品 <b>${posts.length}</b></span><span>有文案 <b>${posts.filter(p=>p.transcript).length}</b></span></div><p class="help-note spaced">最近读取：${date(a.collected_at||a.updated_at)} · 数据以本次实际采集到的公开作品为准。</p>`:''}<ol class="phase-steps connection-steps">${['扫码登录','识别账号','关联工作台','同步作品'].map((s,i)=>`<li class="${i<stage?'done':i===stage?'current':''}"><b>${i<stage?'✓':i+1}</b>${s}</li>`).join('')}</ol><div class="notice spaced" role="status" id="sync-message">${esc(flow.message||(c.status==='connected'?'已识别登录账号，可以刷新作品数据。':'请先在抖音窗口扫码登录。'))}</div>${['failed','cancelled','interrupted'].includes(flow.status)?'<button class="button secondary" data-action="read-mine">重试同步</button>':''}${flow.status==='account_mismatch'?'<p>检测到不同的登录账号。请切回原账号，或在管理工作台中新建工作台。</p>':''}<details class="connection-help"><summary>连接遇到问题？</summary><div id="connection-status">${connectionStatus()}</div><p>平台验证码请在抖音窗口完成。这里的登录资料只保存在本机。</p><div class="actions"><button class="text-button" data-action="connect-douyin">打开抖音窗口</button><button class="text-button" data-action="verify-douyin">重新检测登录</button><button class="text-button" data-action="disconnect-douyin">断开浏览器连接</button><button class="text-button" data-action="clear-douyin">清除本工具登录状态</button></div></details></section>${a?`${panelTitle('我的作品','#account/'+encodeURIComponent(a.sec_uid),'查看全部作品')}${posts.length?`<div class="my-works-preview">${posts.slice(0,8).map(p=>`<article class="panel"><button class="own-work-cover" data-action="preview-video" data-id="${esc(p.aweme_id)}" aria-label="预览 ${esc(p.title)}">${p.image_path?`<img src="${esc(imageSource('post',p.aweme_id))}" alt="${esc(p.title)}">`:'<span>查看作品</span>'}</button><h3><button class="work-preview-title" data-action="preview-video" data-id="${esc(p.aweme_id)}">${esc(p.title)}</button></h3><small>${date(p.published_at)}</small><div class="metric-inline"><span>点赞 ${fmt(p.likes)}</span><span>评论 ${fmt(p.comments)}</span><span>收藏 ${fmt(p.collects)}</span><span>分享 ${fmt(p.shares)}</span></div><div class="actions spaced"><button class="text-button" data-action="preview-transcript" data-id="${esc(p.aweme_id)}">${p.transcript?'阅读文案':p.media_type==='gallery'?'预览图文':'查看视频'}</button><button class="text-button" data-action="view-comments" data-id="${esc(p.aweme_id)}">评论采集</button></div></article>`).join('')}</div>`:emptyState('等待同步作品',busy?'正在读取作品，请稍等。':'刷新作品数据后，采集到的内容会显示在这里。')}`:''}`;
};
settingsPage=function(){return `${pageHead('设置与帮助','日常使用保持简单，组件和配置按需管理。')}<div class="settings-grid"><section class="panel"><h2>工作台与账号</h2><p>当前工作台：${esc(state.data.profile?.name||'尚未选择')}</p><div class="actions"><button class="button secondary" data-action="manage-workspaces">管理工作台</button><a class="text-button" href="#mine">我的抖音账号 →</a></div>${panelTitle('连接与组件')}${productHealth()}<div class="actions spaced"><button class="text-button" data-action="component-help">安装采集 / 转写组件</button><button class="text-button" data-action="prepare-model">准备或检查模型</button></div></section><section class="panel"><h2>快速使用</h2><ol class="guide-list"><li>连接自己的抖音，或粘贴对标账号链接。</li><li>点击作品封面，播放视频、阅读文案和采集评论。</li><li>在设置中配置 AI 接口，选择作品并开始研究。</li><li>在报告页阅读结果，保留来源并导出。</li></ol><details><summary>遇到问题怎么处理？</summary><p>先在任务中心查看具体失败阶段。平台访问问题检查抖音窗口；本地识别问题检查模型与音轨；写入失败检查磁盘。已完成文件与文案会保留。</p><a class="text-button" href="#tasks">打开任务中心 →</a></details></section><section class="panel"><h2>本机数据</h2><p>作品、评论和研究保存在这台电脑，按工作台分别管理。</p><p>升级前请备份本地资料；已下载文件和转写文案可以随时导出。</p><a class="button secondary" href="#materials">查看素材与文案</a></section><section class="panel"><h2>灵思云端试用</h2><p>添加微信，备注「开源体验」。</p><div class="cloud-trial-wechat"><strong>${esc(state.data.brand.wechat)}</strong><button class="button secondary small" data-action="copy-wechat">复制微信号</button></div><p>${esc(state.data.brand.trial_message)}</p><a class="text-button spaced" href="#cloud">了解灵思云端 →</a></section></div>`;};
// Public product introduction only. No local material is used as a marketing sample.
const cloudJourney = [
 {name:'账号定位',short:'他在对谁说话',title:'先看清楚，这个账号为什么值得研究',description:'从账号介绍、作品主题和表达方式出发，理解他面向谁、解决什么问题，再判断哪些观察与你自己的方向相关。',input:'对标账号 · 作品主题',output:'定位与目标用户的基础观察',next:'明确研究对象之后，再看代表作品里的具体做法。',intent:'对标账号研究'},
 {name:'代表作品',short:'从具体作品入手',title:'选几条真实作品，把判断落到内容上',description:'结合已读取的作品与互动数据选取样本，阅读文案、查看评论，为研究结论保留具体依据。',input:'作品样本 · 文案 · 互动',output:'有来源的代表作品研究',next:'样本只代表本次观察，持续追踪可以补充新的依据。',intent:'对标账号研究'},
 {name:'内容结构',short:'理解他怎么表达',title:'拆开内容结构，理解表达如何展开',description:'从开头、用户问题、展开方式和表达特点入手，寻找值得理解的方法，再结合自己的定位思考适用性。',input:'作品文案 · 具体表达',output:'内容结构与表达方式的观察',next:'把有效观察留下来，与后续新增作品对照。',intent:'对标账号研究'},
 {name:'评论反馈',short:'看见观众的问题',title:'从评论里，看见观众还想知道什么',description:'结合实际采集到的评论，观察提问、讨论与疑惑，为继续研究提供线索；评论样本不代表全部受众。',input:'已采集评论 · 对应作品',output:'受众问题与待验证的线索',next:'完成首次研究，接着追踪这个账号的后续内容。',intent:'对标账号研究'}
];
// Original owner-provided QR bytes, embedded for static updates without restarting the service.
const cloudWechatQRImage = "data:image/jpeg;base64,";
function cloudQRCard(){
 const b=state.data.brand;
 if(b.wechat!==b.wechat_qr_owner||b.wechat_qr!=='wechat-qr.jpg')return '';
 return `<figure class="cloud-qr-card"><button class="cloud-qr-image-button" data-action="cloud-qr-large" aria-label="查看微信二维码大图"><img src="${cloudWechatQRImage}" alt="微信 ${esc(b.wechat)} 的添加好友二维码" width="888" height="1131" loading="lazy"></button><figcaption>微信扫一扫，添加好友<div><button class="text-button" data-action="cloud-qr-large">查看大图</button><a href="${cloudWechatQRImage}" download="灵思微信二维码.jpg">保存二维码 ↓</a></div></figcaption></figure>`;
}
function cloudWebsite(){
 try {const u=new URL(state.data.brand.website);if(!['https:','http:'].includes(u.protocol))return '';u.searchParams.set('utm_source','linsi-lite');u.searchParams.set('utm_medium','local-app');return u.toString();}catch{return '';}
}
function cloudTrialButton(label='领取云端试用',intent='完整流程',extra=''){
 return `<button class="button ${extra}" data-action="cloud-trial" data-intent="${esc(intent)}">${esc(label)} <span aria-hidden="true">→</span></button>`;
}
function cloudJourneyPanel(index){
 const step=cloudJourney[index];
 return `<div class="cloud-flow-copy"><span class="cloud-kicker">对标研究 / 0${index+1}</span><h3>${step.title}</h3><p>${step.description}</p><div class="cloud-flow-io"><div><small>从这里开始</small><strong>${step.input}</strong></div><span aria-hidden="true">→</span><div><small>进一步了解</small><strong>${step.output}</strong></div></div><p class="cloud-flow-next">${step.next}</p>${cloudTrialButton('了解'+step.intent+'试用',step.intent,'secondary')}</div>`;
}
const cloudScreens={
 research:{src:'/cloud-research.png',title:'首次账号研究',label:'云端界面展示'},
 knowledge:{src:'/cloud-knowledge.png',title:'账号知识库',label:'云端界面展示'},
 script:{src:'/cloud-script.png',title:'选题与脚本协作',label:'云端界面展示'},
 editor:{src:'/cloud-editor.png',title:'自动剪辑工作台',label:'灵思云端 · 自动剪辑'}
};
function cloudIcon(name){const paths={research:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Zm5-2 6 6M7 10h6M10 7v6',tracking:'M3 12h4l3-7 4 14 3-7h4',growth:'M12 21V11M12 15C4 16 3 10 3 5c6 0 9 3 9 8M12 11c0-6 4-8 9-8 0 5-2 9-9 9',edit:'M4 4l16 16M4 20 20 4M7 7a3 3 0 1 0-6 0 3 3 0 0 0 6 0ZM7 17a3 3 0 1 0-6 0 3 3 0 0 0 6 0Z',book:'M4 3h13a3 3 0 0 1 3 3v15H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3M3 17h17M8 7h7M8 11h5',script:'M4 3h13l3 3v15H4ZM8 8h7M8 12h8M8 16h5',check:'M5 12l4 4L19 6',zoom:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5',feedback:'M4 4h16v12H9l-5 4ZM8 8h8M8 12h5'};return `<svg class="cloud-line-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.check}"/></svg>`;}
function cloudScreenshot(key){const shot=cloudScreens[key];return `<figure class="cloud-product-shot"><button type="button" data-action="cloud-screenshot" data-shot="${key}" aria-label="放大查看${shot.title}"><img src="${shot.src}" alt="灵思云端${shot.title}界面" loading="lazy" decoding="async"><span class="cloud-shot-expand">${cloudIcon('zoom')} 查看大图</span></button><figcaption><span>${shot.title}</span><small>${shot.label}</small></figcaption></figure>`;}
function cloudVisualPoints(items){return `<ul class="cloud-visual-points">${items.map(([icon,title])=>`<li>${cloudIcon(icon)}<span>${title}</span></li>`).join('')}</ul>`;}
function cloudGrowthSection(){return `<section class="cloud-growth cloud-visual-section" id="cloud-growth" tabindex="-1" aria-labelledby="cloud-growth-title"><div class="cloud-section-heading"><div><span class="cloud-kicker">03 / AI 自生长体系</span><h2 id="cloud-growth-title">越用，越有自己的积累。</h2></div><p>把研究、作品与反馈，变成下一次创作的参考。</p></div><div class="cloud-feature-split cloud-growth-showcase"><div class="cloud-visual-copy"><div class="cloud-visual-tabs" role="group" aria-label="查看 AI 自生长界面"><button data-action="cloud-growth-view" data-view="knowledge" aria-pressed="true">${cloudIcon('book')} 账号知识库</button><button data-action="cloud-growth-view" data-view="script" aria-pressed="false">${cloudIcon('script')} 选题与脚本</button></div><div id="cloud-growth-copy"><h3>经验留下来，<br>下次用得上。</h3>${cloudVisualPoints([['research','研究资料归档'],['book','按账号沉淀知识'],['feedback','记录修改与反馈']])}</div>${cloudTrialButton('体验 AI 自生长','AI 自生长体系','secondary')}</div><div id="cloud-growth-screen">${cloudScreenshot('knowledge')}</div></div><div class="cloud-growth-ribbon"><span>${cloudIcon('research')} 研究</span><b>→</b><span>${cloudIcon('book')} 积累</span><b>→</b><span>${cloudIcon('script')} 创作</span><b>→</b><span>${cloudIcon('feedback')} 反馈</span><b>↻</b></div><details class="cloud-small-details"><summary>了解“自生长”</summary><p>围绕你的账号整理研究资料、历史作品与反馈，让下一次选题和脚本有经验可参考；重要判断由你确认。</p></details></section>`;}
function cloudTrackingSection(){return `<section class="cloud-tracking-section cloud-visual-section" id="cloud-tracking" tabindex="-1" aria-labelledby="cloud-tracking-title"><div class="cloud-section-heading"><div><span class="cloud-kicker">02 / 账号追踪</span><h2 id="cloud-tracking-title">新的作品，接着研究。</h2></div><p>从一次了解，到持续关注对标的变化。</p></div><div class="cloud-track-visual" aria-label="账号追踪流程示意"><article>${cloudIcon('tracking')}<h3>发现新作品</h3><p>跟进选定的对标账号</p></article><span class="cloud-track-arrow" aria-hidden="true">→</span><article>${cloudIcon('research')}<h3>观察新变化</h3><p>结合内容与可读取数据</p></article><span class="cloud-track-arrow" aria-hidden="true">→</span><article>${cloudIcon('book')}<h3>补充新积累</h3><p>研究记录回到对应账号</p></article></div><div class="cloud-visual-foot"><small>持续关注账号，积累新的内容观察</small><button class="text-button" data-action="cloud-trial" data-intent="账号追踪">了解账号追踪 →</button></div></section>`;}
cloudPage=function(){const website=cloudWebsite();return `${pageHead('体验灵思云端','从看懂对标，到积累自己的内容能力。')}<div class="cloud-landing cloud-visual-landing">
<section class="cloud-visual-hero" aria-labelledby="cloud-headline"><div><span class="cloud-kicker">灵思云端 · 内容创作与运营</span><h2 id="cloud-headline">看懂对标，<em>做出自己的内容。</em></h2><p>研究有依据，创作有积累。</p></div><div class="cloud-hero-cta">${cloudTrialButton()}<small>微信 ${esc(state.data.brand.wechat)} · 备注「开源体验」</small></div></section>
<nav class="cloud-story-nav cloud-icon-nav" aria-label="云端介绍的四个环节">${[['cloud-research','research','对标研究'],['cloud-tracking','tracking','账号追踪'],['cloud-growth','growth','AI 自生长'],['cloud-editing','edit','自动剪辑']].map(([target,icon,title],i)=>`<button data-action="cloud-scroll" data-target="${target}">${cloudIcon(icon)}<strong>${title}</strong><small>0${i+1}</small></button>`).join('')}</nav>
<section class="cloud-journey-section cloud-visual-section" id="cloud-research" tabindex="-1" aria-labelledby="cloud-journey-title"><div class="cloud-section-heading"><div><span class="cloud-kicker">01 / 对标账号研究</span><h2 id="cloud-journey-title">好内容，先看懂。</h2></div><p>从代表作品入手，建立对一个账号的认识。</p></div><div class="cloud-feature-split"><div class="cloud-visual-copy"><span class="cloud-kicker">首次账号研究</span><h3>选出代表作品，<br>看清内容方法。</h3>${cloudVisualPoints([['research','识别账号与作品'],['check','筛选代表样本'],['book','拆解并沉淀研究']])}${cloudTrialButton('体验云端账号研究','对标账号研究','secondary')}</div>${cloudScreenshot('research')}</div></section>
${cloudTrackingSection()}${cloudGrowthSection()}
<section class="cloud-editing-section cloud-visual-section" id="cloud-editing" tabindex="-1" aria-labelledby="cloud-editing-title"><div class="cloud-section-heading"><div><span class="cloud-kicker">04 / 自动剪辑</span><h2 id="cloud-editing-title">让口播，有声有色。</h2></div><p>先看效果，再了解制作工作台。</p></div><div class="cloud-engine-layout"><div class="cloud-engine-copy"><span class="pill">灵思云端 · 自动剪辑</span><h3>把想表达的重点，<br>放进画面里。</h3><p>点击右侧，试试卡片、颜色和位置。</p>${cloudVisualPoints([['edit','内容匹配动效'],['script','画面自由调整']])}<div class="actions">${cloudTrialButton('了解自动剪辑','自动剪辑')}</div></div>${cloudEngineMarkup()}</div><div class="cloud-editor-peek">${cloudScreenshot('editor')}<div><span class="cloud-kicker">剪辑工作台 · 界面预览</span><h3>一条时间线，<br>看见画面、字幕与动效。</h3><p>从动效方案到细节调整，在同一个工作台里完成。</p><button class="text-button" data-action="cloud-screenshot" data-shot="editor">放大看看工作台 ${cloudIcon('zoom')}</button><small>添加微信，了解适合你的剪辑流程。</small></div></div></section>
<details class="cloud-compare-compact"><summary>本地开源版与云端，有什么区别？ <span>展开对比</span></summary><div class="table-wrap"><table class="comparison"><thead><tr><th>能力</th><th>本地开源体验</th><th>云端进一步体验</th></tr></thead><tbody>${[['对标研究','采集、评论、转写与 API 基础研究','账号研究与内容沉淀'],['持续积累','本机保存与导出','账号追踪、知识库与创作协作'],['自动剪辑','交互动效演示','自动剪辑与成片制作']].map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>
<section class="cloud-invite" aria-labelledby="cloud-invite-title"><div><span class="cloud-kicker">从你的账号开始</span><h2 id="cloud-invite-title">扫码，体验你的内容工作台。</h2><p>添加微信，备注「开源体验」。</p><div class="actions">${cloudTrialButton('领取云端试用')}${website?`<a class="text-button" href="${esc(website)}" target="_blank" rel="noopener noreferrer">访问灵思官网 ↗</a>`:''}</div></div><div class="cloud-contact">${cloudQRCard()}<div class="cloud-contact-text"><small>添加微信</small><strong>${esc(state.data.brand.wechat)}</strong><button class="text-button" data-action="copy-wechat">复制微信号</button></div></div></section>
<section class="cloud-faq" aria-labelledby="cloud-faq-title"><h2 id="cloud-faq-title">常见问题</h2><details><summary>开源版可以继续免费使用吗？</summary><p>可以。已有的本地功能不要求加微信；AI 研究使用你自己配置的接口。</p></details><details><summary>截图里的功能都能在这里使用吗？</summary><p>本地可以使用采集、转写和基础研究，也可体验剪辑动效。截图展示云端工作台，添加微信可了解完整功能与试用方式。</p></details><details><summary>试用期限与额度怎么确认？</summary><p>${esc(state.data.brand.trial_message)}</p></details><details><summary>领取试用会上传我的数据吗？</summary><p>不会。这里只展示微信联系方式，不自动上传账号、素材、报告或 API 配置。</p></details></section></div>`;};
Object.assign(actions,{
 'cloud-screenshot':el=>{const shot=cloudScreens[el.dataset.shot];if(!shot)return;modal(shot.title,`<div class="cloud-shot-viewer"><img src="${shot.src}" alt="灵思云端${shot.title}完整界面"><p>${shot.label} · 截图中的账号与数据为界面示例</p></div>`);},
 'cloud-growth-view':el=>{const key=el.dataset.view;if(!['knowledge','script'].includes(key))return;document.querySelectorAll('[data-action="cloud-growth-view"]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));$('#cloud-growth-screen').innerHTML=cloudScreenshot(key);$('#cloud-growth-copy').innerHTML=key==='knowledge'?`<h3>经验留下来，<br>下次用得上。</h3>${cloudVisualPoints([['research','研究资料归档'],['book','按账号沉淀知识'],['feedback','记录修改与反馈']])}`:`<h3>带着已有积累，<br>推进下一次创作。</h3>${cloudVisualPoints([['book','参考账号知识'],['script','协作选题与脚本'],['feedback','确认与修改表达']])}`;}
});

const cloudTrialIntents=['完整流程','对标账号研究','账号追踪','AI 自生长体系','自动剪辑','选题脚本','发布复盘'];
function cloudTrialText(intent){return `你好，我正在体验灵思开源版，想了解灵思云端试用。\n备注：开源体验${intent==='完整流程'?'':'·'+intent}\n我想了解：${intent}。\n请介绍适用场景、试用方式、期限与额度。`;}
function cloudTrialModal(intent){
 if(!cloudTrialIntents.includes(intent))intent='完整流程';
 const qr=cloudQRCard();
 modal('领取灵思云端试用',`<div class="cloud-trial-dialog ${qr?'cloud-trial-dialog--qr':''}"><p class="cloud-trial-lead">选好想体验的功能，扫码或复制微信号添加好友。</p>${qr}<div class="cloud-trial-form"><label class="field"><span>我想体验</span><select id="cloud-trial-intent">${cloudTrialIntents.map(s=>`<option${s===intent?' selected':''}>${s}</option>`).join('')}</select></label><div class="cloud-trial-wechat"><div><small>微信号</small><strong>${esc(state.data.brand.wechat)}</strong></div><button class="button" data-action="cloud-copy-contact">复制微信号</button></div><p id="cloud-trial-remark">添加时备注「开源体验${intent==='完整流程'?'':'·'+intent}」</p><label class="field"><span>申请说明 · 可直接复制发给我们</span><textarea id="cloud-trial-message" rows="4" readonly>${esc(cloudTrialText(intent))}</textarea></label><button class="button secondary" data-action="cloud-copy-request">复制申请说明</button><p id="cloud-copy-feedback" role="status" aria-live="polite"></p><small>${esc(state.data.brand.trial_message)}</small></div></div>`);
}
async function cloudCopy(value,message){
 try{await navigator.clipboard.writeText(value);$('#cloud-copy-feedback').textContent=message;toast(message);}
 catch{$('#cloud-copy-feedback').textContent='浏览器未允许自动复制，请长按或选中上方文字手动复制。';const input=$('#cloud-trial-message');if(value===input.value){input.focus();input.select();}}
}
Object.assign(actions,{
 'cloud-trial':el=>cloudTrialModal(el.dataset.intent),
 'cloud-scroll':el=>{if(!['cloud-research','cloud-tracking','cloud-growth','cloud-editing'].includes(el.dataset.target))return;const section=document.getElementById(el.dataset.target);section?.focus({preventScroll:true});section?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});},
 'cloud-qr-large':()=>{if(!cloudQRCard())return;const intent=$('#cloud-trial-intent')?.value||'完整流程';modal('微信扫一扫，添加好友',`<div class="cloud-qr-large"><img src="${cloudWechatQRImage}" alt="微信 ${esc(state.data.brand.wechat)} 的添加好友二维码" width="888" height="1131"><p>微信 ${esc(state.data.brand.wechat)} · 添加时备注「开源体验」</p><div class="actions"><a class="button secondary" href="${cloudWechatQRImage}" download="灵思微信二维码.jpg">保存二维码</a>${cloudTrialButton('返回试用说明',intent)}</div></div>`);},
 'cloud-editing':()=>{const section=$('#cloud-editing');section?.focus({preventScroll:true});section?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});},
 'cloud-step':el=>{const index=Number(el.dataset.index);if(!Number.isInteger(index)||!cloudJourney[index])return;document.querySelectorAll('[data-action="cloud-step"]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));$('#cloud-journey-panel').innerHTML=cloudJourneyPanel(index);},
 'cloud-copy-contact':()=>cloudCopy(state.data.brand.wechat,'微信号已复制，去微信搜索并添加。'),
 'cloud-copy-request':()=>cloudCopy($('#cloud-trial-message').value,'申请说明已复制，添加微信后可直接发送。')
});
document.addEventListener('change',e=>{if(e.target.id==='cloud-trial-intent'){const intent=e.target.value;if(!cloudTrialIntents.includes(intent))return;$('#cloud-trial-message').value=cloudTrialText(intent);$('.cloud-trial-lead').textContent='选好想体验的功能，扫码或复制微信号添加好友。';$('#cloud-trial-remark').textContent=`添加时备注「开源体验${intent==='完整流程'?'':'·'+intent}」`;$('#cloud-copy-feedback').textContent='';}});

function previewSequence(post){
 const all=state.data.posts.filter(p=>p.sec_uid===post.sec_uid);
 if(location.hash.startsWith('#account/')&&state.account?.sec_uid===post.sec_uid){const filtered=visiblePosts();if(filtered.some(p=>p.aweme_id===post.aweme_id))return filtered;}
 return all.sort((a,b)=>String(b.published_at||'').localeCompare(String(a.published_at||''))||b.aweme_id.localeCompare(a.aweme_id));
}
Object.assign(actions,{
 'toggle-menu':()=>{const open=document.body.classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));syncNavigationAccess();if(open)$('#sidebar a').focus();},
 'close-menu':()=>{const wasOpen=document.body.classList.contains('menu-open');document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');syncNavigationAccess();if(wasOpen)$('#menu-toggle').focus();},
 'system-health':()=>modal('连接与运行状态',`${productHealth()}<div class="actions spaced"><a class="button secondary" href="#mine" data-action="close-modal">查看抖音连接</a><button class="text-button" data-action="component-help">组件帮助</button></div>`),
 'report-section':el=>document.querySelectorAll('.report-paper h1,.report-paper h2,.report-paper h3,.report-paper h4,.report-paper h5,.report-paper h6')[Number(el.dataset.index)]?.scrollIntoView({block:'start',behavior:'auto'}),
 'copy-material':async el=>{const p=state.data.posts.find(p=>p.aweme_id===el.dataset.id);if(!p?.transcript)throw new Error('当前工作台没有这条文案');await copy(p.transcript);},
 'export-material':el=>{const p=state.data.posts.find(p=>p.aweme_id===el.dataset.id);if(!p?.transcript)throw new Error('当前工作台没有这条文案');const u=URL.createObjectURL(new Blob([p.transcript],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='灵思文案-'+p.aweme_id+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);},
 'preview-adjacent':async el=>{const p=state.data.posts.find(p=>p.aweme_id===mediaDialog?.id);if(!p)return;const list=previewSequence(p),i=list.findIndex(x=>x.aweme_id===p.aweme_id),next=list[i+Number(el.dataset.step)];if(next)await previewVideo(next.aweme_id);},
 'preview-breakdown':async()=>{const p=state.data.posts.find(p=>p.aweme_id===mediaDialog?.id);if(!p?.transcript)throw new Error('请先完成这条作品的文案');const scope=state.scope,r=await api('/api/reports/create',bodyScope({sec_uid:p.sec_uid,aweme_ids:[p.aweme_id],report_type:'breakdown'}));if(scope!==state.scope)return;$('#modal').close();await refresh();location.hash='#report/'+r.id;}
});
const basePreviewTranscript=previewTranscript;
previewTranscript=function(post){return basePreviewTranscript(post)+(post.transcript?`<div class="actions"><button class="text-button" data-action="copy-material" data-id="${esc(post.aweme_id)}">复制文案</button><button class="text-button" data-action="export-material" data-id="${esc(post.aweme_id)}">导出 TXT</button><button class="button secondary small" data-action="preview-breakdown">拆解这条作品</button></div>`:'');};
const basePreviewVideo=previewVideo;
previewVideo=async function(id,focus){const scope=state.scope;const p=state.data.posts.find(x=>x.aweme_id===id);if(!p)return;const list=previewSequence(p),i=list.findIndex(x=>x.aweme_id===id);await basePreviewVideo(id,focus);if(mediaDialog?.id!==id||scope!==state.scope)return;const heading=$('.preview-title');if(heading&&!$('.preview-navigation'))heading.insertAdjacentHTML('afterend',`<div class="preview-navigation"><button class="button secondary small" data-action="preview-adjacent" data-step="-1" ${i===0?'disabled':''}>← 上一条</button><small>${i+1} / ${list.length}</small><button class="button secondary small" data-action="preview-adjacent" data-step="1" ${i===list.length-1?'disabled':''}>下一条 →</button></div>`);};
document.addEventListener('input',e=>{if(e.target.id==='account-search'){state.accountQuery=e.target.value;renderAccountLibrary();}if(e.target.id==='material-search'){state.materialQuery=e.target.value;renderMaterials();}});
document.addEventListener('change',e=>{if(e.target.id==='account-sort'){state.accountSort=e.target.value;renderAccountLibrary();}if(e.target.id==='material-account'){state.materialAccount=e.target.value;renderMaterials();}if(e.target.id==='material-filter'){state.materialFilter=e.target.value;renderMaterials();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')actions['close-menu']();});
let modalOpener;
document.addEventListener('click',e=>{if(e.target.closest('[data-action]')&&!$('#modal').open)modalOpener=e.target.closest('[data-action]');},true);
$('#modal').addEventListener('close',()=>{if(modalOpener?.isConnected)modalOpener.focus({preventScroll:true});});

function syncNavigationAccess(){const mobile=matchMedia('(max-width:750px)').matches;const open=document.body.classList.contains('menu-open');$('#sidebar').inert=mobile&&!open;$('.workspace').inert=mobile&&open;}
matchMedia('(max-width:750px)').addEventListener('change',syncNavigationAccess);syncNavigationAccess();

// Keep an image failure local to the affected tile; retry only the cached image request.
document.addEventListener('error',e=>{const img=e.target;if(!(img instanceof HTMLImageElement)||!img.src.includes('/api/image'))return;img.hidden=true;const parent=img.parentElement;if(img._retryButton?.isConnected)return;const button=document.createElement('button');img._retryButton=button;button.type='button';button.className='image-retry';button.textContent='图片未加载 · 重试';button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();button.textContent='正在重试…';const url=new URL(img.src);url.searchParams.set('retry',Date.now());img.onload=()=>{img.hidden=false;button.remove();};img.onerror=()=>{button.textContent='图片未加载 · 重试';};img.src=url;});if(parent.tagName==='BUTTON'||parent.tagName==='A'){parent.insertAdjacentElement('afterend',button);}else parent.append(button);},true);

