// Lifecycle for the public desktop demo. Nothing is uploaded or generated here.
let cloudEngineController=null;
function syncCloudEngine(){
 const root=document.querySelector('.cloud-engine-demo');
 if(cloudEngineController?.root===root)return;
 cloudEngineController?.dispose();cloudEngineController=null;
 if(!root)return;
 const abort=new AbortController(),signal=abort.signal;
 const engineDemo=root,engineVideo=root.querySelector('#engine-video'),enginePlay=root.querySelector('#engine-play');
 const engineVideoStatus=root.querySelector('#engine-video-status'),engineReplay=root.querySelector('#engine-replay');
 const engineOverlay=root.querySelector('.engine-overlay'),engineEffects=[...root.querySelectorAll('[data-engine-effect]')];
 const engineScenes=[...root.querySelectorAll('[data-engine-scene]')],reduced=matchMedia('(prefers-reduced-motion:reduce)');
 const motionEnabled=()=>!reduced.matches;
 let engineEffectsVisible=false,engineEffectAnimations=[],placementAnimation=null,visible=false,choice=null,tourTimer=null,tourRemaining=6,interacted=false,disposed=false;
 const listen=(target,name,fn)=>target.addEventListener(name,fn,{signal});
 const copy={steps:['把复杂内容，拆成清楚的三步。','分步展开','逐条呈现'],focus:['讲到关键处，让重点跳出来。','重点强调','划线聚焦'],data:['数字的变化，用画面说清楚。','柱状生长','数字浮现'],compare:['前后放在一起，差别一眼看见。','双向入场','对比呈现'],icons:['从想法到方向，图标跟着出现。','弹性入场','轻波纹'],tech:['让科技感，成为画面的一部分。','扫描光线','环形运转'],network:['文字、画面、声音，逐一连接。','节点点亮','路径连线']};
 function clearTour(){clearTimeout(tourTimer);tourTimer=null;}
 function cancelEngineEffects(){engineEffectAnimations.forEach(a=>a.cancel());engineEffectAnimations=[];}
 function settle(){clearTour();cancelEngineEffects();placementAnimation?.cancel();placementAnimation=null;root.classList.remove('effects-running');}
     function playEngineEffect() {
        cancelEngineEffects();
        if (!motionEnabled() || !engineEffectsVisible || document.hidden || engineDemo.dataset.mode === 'original') return;
        const scene = engineScenes.find(item => !item.hidden);
        if (typeof scene.animate !== 'function') return;
        const animate = (element, frames, duration = 650, delay = 0, easing = 'cubic-bezier(.22,.8,.25,1)') => {
            engineEffectAnimations.push(element.animate(frames, {
                duration, delay, easing, fill:'both', iterations:1
            }));
        };
        animate(scene, [{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}], 420);
        switch (engineDemo.dataset.effect) {
            case 'steps':
                scene.querySelectorAll('li').forEach((item, index) => animate(item, [
                    {opacity:0,transform:'translateX(-14px)'},
                    {opacity:1,transform:'translateX(3px)',offset:.75},
                    {opacity:1,transform:'translateX(0)'}
                ], 650, 180 + index * 430));
                break;
            case 'focus':
                animate(scene.querySelector('.engine-keyword'), [{opacity:0,transform:'scale(.85)'},{opacity:1,transform:'scale(1.04)',offset:.7},{opacity:1,transform:'scale(1)'}], 750, 200);
                animate(scene.querySelector('.engine-marker'), [{transform:'scaleX(0)'},{transform:'scaleX(1)'}], 700, 650);
                break;
            case 'data':
                scene.querySelectorAll('.engine-bar').forEach((item, index) => animate(item, [{transform:'scaleY(0)'},{transform:'scaleY(1)'}], 1000, 180 + index * 240));
                scene.querySelectorAll('b').forEach((item, index) => animate(item, [{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}], 500, 650 + index * 240));
                break;
            case 'compare':
                scene.querySelectorAll('.engine-compare-card').forEach((item, index) => animate(item, [{opacity:0,transform:'translateX(' + (index ? 16 : -16) + 'px)'},{opacity:1,transform:'translateX(0)'}], 800, 180 + index * 550));
                animate(scene.querySelector('svg'), [{opacity:0,transform:'scale(.5)'},{opacity:1,transform:'scale(1.18)',offset:.7},{opacity:1,transform:'scale(1)'}], 500, 1250);
                break;
            case 'icons':
                scene.querySelectorAll('.engine-icon-tile').forEach((item, index) => animate(item, [{opacity:0,transform:'translateY(15px) scale(.65)'},{opacity:1,transform:'translateY(-3px) scale(1.05)',offset:.7},{opacity:1,transform:'translateY(0) scale(1)'}], 850, 150 + index * 480));
                scene.querySelectorAll('.engine-icon-ring').forEach((item, index) => animate(item, [{opacity:0,transform:'scale(.8)'},{opacity:.45,transform:'scale(1)',offset:.2},{opacity:0,transform:'scale(1.8)'}], 850, 700 + index * 480));
                break;
            case 'tech':
                scene.querySelectorAll('.engine-tech-ring').forEach((item, index) => animate(item, [{transform:'rotate(0deg)'},{transform:'rotate(' + (index ? -270 : 360) + 'deg)'}], 3400, 150, 'linear'));
                animate(scene.querySelector('.engine-tech-core'), [{opacity:0,transform:'scale(.55)'},{opacity:1,transform:'scale(1.08)',offset:.7},{opacity:1,transform:'scale(1)'}], 850, 200);
                animate(scene.querySelector('.engine-tech-scan'), [{opacity:0,transform:'translateY(0)'},{opacity:.85,offset:.12},{opacity:.85,transform:'translateY(65px)',offset:.47},{opacity:.85,transform:'translateY(0)',offset:.84},{opacity:0,transform:'translateY(0)'}], 2800, 450, 'linear');
                scene.querySelectorAll('.engine-tech-corner').forEach(item => animate(item, [{opacity:0},{opacity:1}], 700, 600));
                break;
            case 'network':
                animate(scene.querySelector('.engine-network-core'), [{opacity:0,transform:'scale(.6)'},{opacity:1,transform:'scale(1)'}], 600, 100);
                scene.querySelectorAll('.engine-network-line').forEach((item, index) => animate(item, [{strokeDashoffset:'1',opacity:0},{strokeDashoffset:'0',opacity:.5}], 650, 350 + index * 300));
                scene.querySelectorAll('.engine-network-node').forEach((item, index) => animate(item, [{opacity:0},{opacity:1}], 550, 650 + index * 300));
                scene.querySelectorAll('.engine-network-dot').forEach((item, index) => animate(item, [{transform:'scale(.5)'},{transform:'scale(1.15)',offset:.7},{transform:'scale(1)'}], 650, 650 + index * 300));
                animate(scene.querySelector('.engine-network-pulse'), [{opacity:0,transform:'scale(.6)'},{opacity:.4,offset:.25},{opacity:0,transform:'scale(1.7)'}], 1000, 1900);
                break;
        }
    }

 // Card demonstrations remain interactive when the source video is paused or unavailable.
 function canRun(){return !disposed&&visible&&!document.hidden&&motionEnabled()&&root.dataset.mode==='engine';}
 function updatePlayback(){enginePlay.textContent=engineVideo.paused?'播放视频':'暂停视频';enginePlay.setAttribute('aria-pressed',String(!engineVideo.paused));}
 function syncEffects(){
  clearTour();root.classList.toggle('effects-running',canRun());
  if(!canRun()){settle();return;}
  if(!engineEffectAnimations.length)playEngineEffect();
  if(!interacted&&tourRemaining>0)tourTimer=setTimeout(()=>{tourRemaining--;const current=engineEffects.findIndex(b=>b.dataset.engineEffect===root.dataset.effect);selectEffect(engineEffects[(current+1)%engineEffects.length].dataset.engineEffect);},4400);
 }
 function selectEffect(key){
  if(!copy[key])return;settle();root.dataset.effect=key;
  engineScenes.forEach(scene=>{scene.hidden=scene.dataset.engineScene!==key;});
  engineEffects.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.engineEffect===key)));
  const [subtitle,first,second]=copy[key];root.querySelector('.engine-subtitle span').textContent=subtitle;
  const tracks=root.querySelectorAll('.engine-track:first-child .engine-track-lane span');tracks[0].textContent=first;tracks[1].textContent=second;
  syncEffects();
 }
 function syncPlayback(){
  const shouldPlay=!disposed&&visible&&!document.hidden&&(choice===true||(choice===null&&motionEnabled()));
  if(!shouldPlay||engineVideo.error){engineVideo.pause();return;}
  engineVideo.play().catch(error=>{if(disposed||error.name==='AbortError'||engineVideo.error)return;choice=false;engineVideoStatus.textContent='点击播放视频 · 无声演示';updatePlayback();});
 }
 function manual(){interacted=true;clearTour();}
 listen(root,'pointerdown',manual);listen(root,'focusin',manual);
 listen(enginePlay,'click',()=>{manual();choice=engineVideo.paused;syncPlayback();});
 listen(engineVideo,'play',updatePlayback);
 listen(engineVideo,'pause',updatePlayback);
 listen(engineVideo,'playing',()=>{engineVideoStatus.textContent='数字人 · 无声演示';});
 listen(engineVideo,'waiting',()=>{engineVideoStatus.textContent='正在载入视频…';});
 listen(engineVideo,'error',()=>{enginePlay.disabled=true;engineVideoStatus.textContent='视频暂不可用 · 动效可体验';const help=root.querySelector('.engine-load-help');help.hidden=false;help.textContent='视频文件未能加载。请重新启动灵思后刷新本页；卡片、颜色和位置效果仍可体验。';root.querySelector('.engine-retry').hidden=false;});
 listen(root.querySelector('.engine-retry'),'click',()=>{enginePlay.disabled=false;engineReplay.disabled=false;root.querySelector('.engine-load-help').hidden=true;root.querySelector('.engine-retry').hidden=true;choice=true;engineVideo.load();syncPlayback();});
 listen(engineReplay,'click',()=>{manual();cancelEngineEffects();syncEffects();});
 for(const button of root.querySelectorAll('[data-engine-mode]'))listen(button,'click',()=>{
  manual();settle();root.dataset.mode=button.dataset.engineMode;
  root.querySelectorAll('[data-engine-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
  root.querySelectorAll('[data-engine-effect],[data-engine-tone],[data-engine-placement]').forEach(b=>{b.disabled=root.dataset.mode==='original';});
  engineReplay.disabled=root.dataset.mode==='original'||!motionEnabled();
  syncEffects();
 });
 for(const button of engineEffects)listen(button,'click',()=>{manual();selectEffect(button.dataset.engineEffect);});
 for(const setting of ['tone','placement']){
  const buttons=[...root.querySelectorAll('[data-engine-'+setting+']')],key='engine'+setting[0].toUpperCase()+setting.slice(1);
  for(const button of buttons)listen(button,'click',()=>{
   manual();if(root.dataset[setting]===button.dataset[key])return;
   const from=setting==='placement'?engineOverlay.getBoundingClientRect():null;placementAnimation?.cancel();placementAnimation=null;
   root.dataset[setting]=button.dataset[key];buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
   if(from&&canRun()){
    const to=engineOverlay.getBoundingClientRect();placementAnimation=engineOverlay.animate([{transform:`translate(${from.left-to.left}px,${from.top-to.top}px)`},{transform:'translate(0,0)'}],{duration:560,easing:'cubic-bezier(.22,.8,.25,1)'});
   }
  });
 }
 listen(document,'visibilitychange',()=>{syncPlayback();syncEffects();});
 listen(window,'resize',()=>{placementAnimation?.cancel();placementAnimation=null;});
 listen(reduced,'change',()=>{choice=null;settle();engineReplay.disabled=!motionEnabled()||root.dataset.mode==='original';syncPlayback();syncEffects();});
 const observer=new IntersectionObserver(entries=>{const before=visible;visible=engineEffectsVisible=entries[0].isIntersecting&&entries[0].intersectionRatio>=.15;if(before!==visible){syncPlayback();syncEffects();}},{threshold:.15});
 root.classList.add('video-enhanced');engineVideo.controls=false;engineVideo.muted=true;engineReplay.disabled=!motionEnabled();updatePlayback();observer.observe(root.querySelector('.engine-screen'));
 cloudEngineController={root,dispose(){disposed=true;settle();observer.disconnect();abort.abort();engineVideo.pause();engineVideo.removeAttribute('src');engineVideo.load();}};
}
